/**
 * Single-tag filter for a list of subjects of one kind. Only tags that apply to `kind` are offered. Renders nothing
 * for a person who may not read tags here, so the filter row never shows a tag load error.
 */
export const TagFilter = ({ catalog, kind, label, onChange, value }: TagFilterProps) => {
  const own = useTagCatalog(kind, catalog === undefined);
  const resolved = catalog ?? own;
  if (resolved.status === 'forbidden') {
    return null;
  }
  return (
    <TagI18n>
      <TagFilterForm
        catalog={resolved}
        kind={kind}
        {...(label === undefined ? {} : { label })}
        onChange={onChange}
        value={value}
      />
    </TagI18n>
  );
};

const subjectChunkSize = 500;

export interface BulkTagDialogProps {
  kind: SubjectKind;
  onDone: () => void;
  onOpenChange: (open: boolean) => void;
  open: boolean;
  /** Panel width; defaults to `md`. Pages whose other panels are wider pass their size. */
  size?: SidePanelSize;
  subjectIds: readonly SubjectId[];
}

const bulkFailureValues = Schema.Literals(['none', 'retry', 'forbidden']);
type BulkFailure = typeof bulkFailureValues.Type;

/** A refused tag read or apply command: retrying will not help, so the panel says so. */
const isForbidden = (failure: TagCallFailure) =>
  isTagReadForbidden(failure) ||
  Schema.is(AssignTagActionForbiddenProblemSchema)(failure) ||
  Schema.is(UnassignTagActionForbiddenProblemSchema)(failure);

interface BulkTagDraft {
  readonly mode: BulkMode;
  readonly tagId: TagId | null;
}

const emptyBulkTagDraft: BulkTagDraft = { mode: 'add', tagId: null };

/** The tag and add/remove of the bulk panel. Uložit sends them through the panel's save bar, never the form. */
const bulkTagForm = FormReact.make(FormBuilder.empty.addField('mode', Schema.String).addField('tagId', Schema.String), {
  fields: { mode: RadioField, tagId: ComboboxField },
  onSubmit: () => Effect.void,
  runtime: browserAtomRuntime,
});
type BulkTagValues = typeof bulkTagForm.schema.Encoded;
const emptyBulkTagValues: BulkTagValues = { mode: emptyBulkTagDraft.mode, tagId: '' };

/** The choice the form holds: a picked tag is only ever one the picker offered from the loaded catalog. */
const bulkTagDraftOf = (values: BulkTagValues): BulkTagDraft => ({
  mode: isBulkMode(values.mode) ? values.mode : emptyBulkTagDraft.mode,
  tagId: Option.getOrNull(Schema.decodeUnknownOption(TagIdSchema)(values.tagId)),
});

/**
 * Picking the tag and add/remove changes only the draft; the shared Save button ("Uložit", last in the footer) applies
 * it to every selected subject, and leaving a started choice asks Uložit / Zahodit změny / Zůstat first.
 */
const BulkTagDialogContent = ({ kind, onDone, onOpenChange, open, size = 'md', subjectIds }: BulkTagDialogProps) => {
  const { language, t } = useModernI18n();
  const toaster = useToast();
  const values = Option.getOrElse(useAtomValue(bulkTagForm.values), () => emptyBulkTagValues);
  const setValues = useAtomSet(bulkTagForm.setValues);
  const draft = bulkTagDraftOf(values);
  const { tagId } = draft;
  const [failure, setFailure] = useState<BulkFailure>('none');
  const [pendingMessage, setPendingMessage] = useState<string | null>(null);
  // The picker reads the same shared catalog; a refusal means this role may not tag at all, so the panel says so.
  const readable = tagsReadable();
  const catalog = useTagCatalogSnapshot(open && readable);
  const catalogForbidden = !readable || (catalog.state === 'failed' && isForbidden(catalog.error));
  const forbidden = catalogForbidden || failure === 'forbidden';

  const apply = (value: BulkTagDraft, chosen: TagId): Effect.Effect<SaveOutcome> => {
    const operation = value.mode === 'add' ? assignTag : unassignTag;
    const subjects: Subject[] = subjectIds.map((id) => ({ id, kind }));
    const chunks = Array.from({ length: Math.ceil(subjects.length / subjectChunkSize) }, (_, index) =>
      subjects.slice(index * subjectChunkSize, (index + 1) * subjectChunkSize),
    );
    return Effect.forEach(chunks, (part) => operation(chosen, part), { concurrency: 1, discard: true }).pipe(
      Effect.match({
        onFailure: (error): SaveOutcome => {
          const pending = pendingProposalMessage(error);
          setPendingMessage(pending ?? null);
          setFailure(isForbidden(error) ? 'forbidden' : 'retry');
          return pending === undefined ? 'failed' : 'proposed';
        },
        onSuccess: (): SaveOutcome => {
          setFailure('none');
          return 'saved';
        },
      }),
    );
  };
  const record = useDraftSave<BulkTagDraft, never>({
    isValid: (value) => value.tagId !== null && subjectIds.length > 0 && !forbidden,
    open,
    runtime: browserRuntime,
    save: (value) => (value.tagId === null ? Effect.succeed<SaveOutcome>('failed') : apply(value, value.tagId)),
    value: draft,
  });
  const blocker = useBlocker({ enableBeforeUnload: false, shouldBlockFn: () => record.dirty, withResolver: true });

  const close = () => {
    setValues(emptyBulkTagValues);
    // The panel can stay mounted while closed: the next opening starts from an empty choice again.
    record.adopt(emptyBulkTagDraft);
    setFailure('none');
    setPendingMessage(null);
    onOpenChange(false);
  };
  const guard = useUnsavedChangesGuard({ draft: record, navigation: blocker, onDiscard: constVoid });
  const labels = saveLabelsFor(language);
  const handleReloadLatest = constVoid;
  const handleSave = () => {
    record.save();
    record.afterSave((status) => {
      if (status === 'saved') {
        toaster.create({ title: t('tagging.tags.bulk.success'), type: 'success' });
        onDone();
        close();
      }
    });
  };

  const tagError = record.status === 'invalid' && tagId === null;
  return (
    <>
      <SidePanel
        actions={
          <>
            <Button
              appearance="outline"
              disabled={record.status === 'saving'}
              onClick={() => guard.request(close)}
              severity="secondary"
              size="sm"
            >
              {t('tagging.tags.form.cancel')}
            </Button>
            <SaveBar
              labels={labels}
              onReloadLatest={handleReloadLatest}
              onSave={handleSave}
              size="sm"
              status={record.status}
            />
          </>
        }
        description={t('tagging.tags.bulk.description', { total: subjectIds.length })}
        guard={guard}
        // The first field takes focus, not the close button the panel renders first.
        initialFocusEl={() => globalThis.document.querySelector<HTMLElement>('[id="combobox:bulk-tag-picker:input"]')}
        onOpenChange={(next) => {
          if (!next && record.status !== 'saving') {
            close();
          }
        }}
        open={open}
        resizeLabel={t('tagging.sidePanel.resize')}
        size={size}
        title={t('tagging.tags.bulk.title')}
      >
        <FormRoot
          className="flex flex-col gap-200 py-200"
          defaultValues={emptyBulkTagValues}
          form={bulkTagForm}
          translateMessage={(message) => t(message)}
        >
          {forbidden && (
            <StatusText showIcon status="error">
              {t('tagging.tags.bulk.forbidden')}
            </StatusText>
          )}
          {!forbidden && failure === 'retry' && (
            <StatusText showIcon status="error">
              {pendingMessage ?? t('tagging.tags.bulk.failure')}
            </StatusText>
          )}
          {!forbidden && (
            <TagPickerField
              Bound={bulkTagForm.tagId}
              clearable={false}
              enabled={open}
              helpText={tagError ? t('tagging.tags.bulk.chooseTag') : ''}
              id="bulk-tag-picker"
              invalid={tagError}
              kind={kind}
              labelKey="tagging.tags.bulk.tag"
              picked={values.tagId}
            />
          )}
          <bulkTagForm.mode
            disabled={forbidden}
            items={[
              { label: t('tagging.tags.bulk.add'), value: 'add' },
              { label: t('tagging.tags.bulk.remove'), value: 'remove' },
            ]}
            label={t('tagging.tags.bulk.action')}
          />
        </FormRoot>
      </SidePanel>
      <UnsavedChangesDialog labels={labels} prompt={guard.prompt} />
    </>
  );
};

/** Adds or removes one tag on the selected subjects. Idempotent on the server: rows already in that state are skipped. */
export const BulkTagDialog = (props: BulkTagDialogProps) => (
  <TagI18n>
    <BulkTagDialogContent {...props} />
  </TagI18n>
);

export interface TagControlsProps {
  /** Subjects of this kind whose tags the filter selects. */
  kind: SubjectKind;
  /** Visible label above the filter, already translated. */
  label?: string;
  onChange: (tagId: TagId | null) => void;
  value: TagId | null;
}

/**
 * The module's public component: the localized single-tag filter of one subject kind, ready for the Shell to load
 * through the generated `./TagControls` Module Federation exposure. The host owns the selected `value`; the filter
 * reads the shared tag catalog and renders nothing for a person who may not read tags here.
 */
export const TagControls = ({ kind, label, onChange, value }: TagControlsProps) => (
  <TagI18n>
    <TagFilter kind={kind} {...(label === undefined ? {} : { label })} onChange={onChange} value={value} />
  </TagI18n>
);

export default TagControls;
